import Foundation

/// 수학 개념 사전 보충: 중학교 교과서 단원 (2015·2022 개정)
extension DoitCurriculum {
    static let mathMiddleMore: [CurriculumEntry] = [
        // 중1
        ce(.middle, "정수와 유리수", ["수의 대소 관계", "수직선", "부등호의 사용"], "수직선에서 오른쪽에 있는 수가 왼쪽에 있는 수보다 커요. 양수는 0보다 크고 음수는 0보다 작으며, 양수끼리는 절댓값이 큰 수가 크고 음수끼리는 절댓값이 큰 수가 작아요. 'x는 −2 이상 3 미만이다'는 −2 ≤ x < 3처럼 부등호로 나타내요.\n예: −5 < −2 < 0 < 1.5 < 3, 절댓값이 2 이하인 정수는 −2, −1, 0, 1, 2로 5개예요."),
        ce(.middle, "문자와 식", ["식의 값", "대입"], "식에 있는 문자 대신 수를 바꾸어 넣는 것을 대입이라 하고, 대입하여 계산한 결과를 식의 값이라고 해요. 음수를 대입할 때는 반드시 괄호를 써서 부호를 실수하지 않도록 해요.\n예: x = −2일 때 3x + 5 = 3 × (−2) + 5 = −1, x² = (−2)² = 4"),
        ce(.middle, "문자와 식", ["일차방정식의 활용", "방정식의 활용", "방정식 문장제"], "문장으로 된 문제는 ① 구하려는 것을 x로 놓고 ② 수량 사이의 관계를 방정식으로 세운 뒤 ③ 풀어서 ④ 답이 문제의 뜻에 맞는지 확인해요. 거리·속력·시간 문제는 (거리) = (속력) × (시간)을 이용해요.\n예: 연속하는 세 자연수의 합이 48이면 (x − 1) + x + (x + 1) = 48, 3x = 48이므로 세 수는 15, 16, 17"),
        ce(.middle, "좌표평면과 그래프", ["그래프의 해석", "그래프", "상황을 나타낸 그래프"], "두 양 사이의 관계를 좌표평면 위에 점, 직선, 곡선 등으로 나타낸 것을 그래프라고 해요. 그래프를 보면 시간에 따라 양이 늘어나는지, 줄어드는지, 일정한지 같은 변화를 한눈에 알 수 있어요.\n예: 시간-거리 그래프가 수평인 구간은 이동하지 않고 멈춰 있는 시간이에요."),
        ce(.middle, "좌표평면과 그래프", ["정비례 관계의 그래프", "y = ax의 그래프"], "정비례 관계 y = ax (a ≠ 0)의 그래프는 원점을 지나는 직선이에요. a > 0이면 제1사분면과 제3사분면을 지나며 오른쪽 위로 향하고, a < 0이면 제2사분면과 제4사분면을 지나며 오른쪽 아래로 향해요. a의 절댓값이 클수록 그래프가 y축에 가까워져요.\n예: y = 3x의 그래프는 점 (1, 3)을 지나고, y = −x의 그래프는 점 (1, −1)을 지나요."),
        ce(.middle, "좌표평면과 그래프", ["반비례 관계의 그래프", "y = a/x의 그래프"], "반비례 관계 y = a/x (a ≠ 0)의 그래프는 좌표축에 한없이 가까워지는 한 쌍의 매끄러운 곡선이에요. a > 0이면 제1사분면과 제3사분면에, a < 0이면 제2사분면과 제4사분면에 그려져요. 그래프 위의 점에서 x와 y를 곱한 값은 항상 a예요.\n예: y = 6/x의 그래프는 점 (2, 3), (−3, −2)를 지나요."),
        ce(.middle, "기본 도형과 작도", ["점, 선, 면", "교점과 교선", "도형의 기본 요소"], "점이 움직인 자리는 선, 선이 움직인 자리는 면이 되고, 점·선·면은 도형을 이루는 기본 요소예요. 선과 선 또는 선과 면이 만나서 생기는 점을 교점, 면과 면이 만나서 생기는 선을 교선이라고 해요.\n예: 직육면체에서 교점의 개수는 꼭짓점의 개수와 같은 8개, 교선의 개수는 모서리의 개수와 같은 12개예요."),
        ce(.middle, "기본 도형과 작도", ["직선, 반직선, 선분", "반직선", "선분"], "두 점 A, B를 지나는 끝없이 곧은 선을 직선 AB, 점 A에서 시작하여 점 B의 방향으로 끝없이 뻗은 선을 반직선 AB, 두 점 A, B를 잇는 곧은 선 중 A에서 B까지 부분을 선분 AB라고 해요. 두 점을 잇는 선 중 가장 짧은 선분 AB의 길이를 두 점 A, B 사이의 거리라고 해요.\n예: 반직선 AB와 반직선 BA는 시작점과 방향이 달라서 서로 다른 반직선이에요."),
        ce(.middle, "기본 도형과 작도", ["각의 분류", "평각", "예각과 둔각"], "한 점에서 시작하는 두 반직선으로 이루어진 도형을 각이라고 해요. 크기가 180°인 각을 평각, 90°인 각을 직각, 0°보다 크고 90°보다 작은 각을 예각, 90°보다 크고 180°보다 작은 각을 둔각이라고 해요.\n예: 35°는 예각, 120°는 둔각이에요."),
        ce(.middle, "기본 도형과 작도", ["수직과 수선", "수직이등분선", "수선의 발"], "두 직선이 만나서 이루는 각이 직각일 때 두 직선은 서로 수직이고, 한 직선을 다른 직선의 수선이라고 해요. 선분의 중점을 지나고 그 선분에 수직인 직선을 수직이등분선이라고 해요. 직선 밖의 한 점에서 직선에 수선을 그었을 때 생기는 교점을 수선의 발이라고 해요.\n예: 선분 AB의 수직이등분선 위의 점은 두 점 A, B에서 같은 거리에 있어요."),
        ce(.middle, "기본 도형과 작도", ["위치 관계", "꼬인 위치", "두 직선의 위치 관계", "직선과 평면의 위치 관계"], "평면에서 두 직선은 한 점에서 만나거나, 평행하거나, 일치해요. 공간에서는 여기에 더해 만나지도 않고 평행하지도 않은 경우가 있는데, 이것을 꼬인 위치에 있다고 해요. 공간에서 직선과 평면은 한 점에서 만나거나, 평행하거나, 직선이 평면에 포함돼요.\n예: 직육면체에서 한 모서리와 꼬인 위치에 있는 모서리는 4개예요."),
        ce(.middle, "평면도형과 입체도형", ["회전체", "회전축", "회전체의 단면"], "평면도형을 한 직선을 축으로 하여 1회전 시킬 때 생기는 입체도형을 회전체라 하고, 그 직선을 회전축이라고 해요. 원기둥, 원뿔, 원뿔대, 구가 대표적인 회전체예요. 회전체를 회전축에 수직인 평면으로 자르면 단면은 항상 원이고, 회전축을 포함하는 평면으로 자르면 단면은 회전축에 대하여 선대칭도형이에요.\n예: 직사각형을 한 변을 축으로 회전시키면 원기둥, 직각삼각형을 직각을 낀 한 변을 축으로 회전시키면 원뿔이 돼요."),
        ce(.middle, "자료의 정리와 해석", ["줄기와 잎 그림", "stem-and-leaf plot"], "자료를 줄기와 잎으로 나누어 나타낸 그림을 줄기와 잎 그림이라고 해요. 보통 십의 자리 숫자를 줄기, 일의 자리 숫자를 잎으로 하고, 잎은 크기순으로 적어요. 자료의 분포와 각각의 값을 함께 볼 수 있어요.\n예: 23, 27, 31, 35, 38은 줄기 2에 잎 3, 7, 줄기 3에 잎 1, 5, 8로 나타내요."),
        ce(.middle, "자료의 정리와 해석", ["도수분포다각형", "도수분포다각형의 넓이"], "히스토그램에서 각 직사각형의 윗변의 중점을 차례로 선분으로 연결하고, 양 끝에 도수가 0인 계급이 하나씩 더 있는 것으로 생각하여 그 중점까지 연결한 그래프를 도수분포다각형이라고 해요. 도수분포다각형과 가로축으로 둘러싸인 부분의 넓이는 히스토그램의 직사각형의 넓이의 합과 같아요.\n예: 계급의 크기가 5이고 도수의 총합이 30이면 도수분포다각형과 가로축으로 둘러싸인 부분의 넓이는 5 × 30 = 150이에요."),
        ce(.middle, "자료의 정리와 해석", ["상대도수의 분포", "상대도수의 분포표", "상대도수의 그래프"], "각 계급의 상대도수를 나타낸 표를 상대도수의 분포표라고 하고, 이를 히스토그램이나 도수분포다각형 모양의 그래프로 나타낼 수 있어요. 상대도수를 이용하면 도수의 총합이 다른 두 자료의 분포를 비교하기 좋아요.\n예: A반 25명 중 5명, B반 40명 중 6명이 90점 이상이면 상대도수는 0.2와 0.15이므로 A반의 비율이 더 높아요."),
        ce(.middle, "자료의 정리와 해석", ["통계적 탐구", "통계적 문제 해결"], "통계적 탐구는 ① 궁금한 문제를 정하고 ② 자료를 수집하고 ③ 표나 그래프로 정리·분석한 뒤 ④ 결과를 해석하여 결론을 내리는 과정이에요. 자료를 모을 때는 조사 대상과 방법이 문제에 알맞은지 확인해야 해요.\n예: 우리 반 학생들의 하루 스마트폰 사용 시간을 조사해 도수분포표와 히스토그램으로 정리하고 특징을 해석해요."),

        // 중2
        ce(.middle, "유리수와 순환소수", ["유한소수와 무한소수", "유한소수", "무한소수"], "소수점 아래에 0이 아닌 숫자가 유한 개인 소수를 유한소수, 무한히 계속되는 소수를 무한소수라고 해요. 기약분수로 나타냈을 때 분모의 소인수가 2나 5뿐이면 그 분수는 유한소수로 나타낼 수 있어요. 분모에 2와 5 이외의 소인수가 있으면 순환소수가 돼요.\n예: 7/20 = 0.35 (20 = 2² × 5)는 유한소수, 1/6 = 0.1666…은 순환소수예요."),
        ce(.middle, "유리수와 순환소수", ["순환소수를 분수로 나타내기", "순환소수의 분수 표현"], "순환소수를 x로 놓고 순환마디가 시작되는 위치에 맞추어 10의 거듭제곱을 곱한 두 식을 만든 뒤 빼면 소수 부분이 사라져요. 간단히, 순환마디가 소수점 바로 아래에서 시작하면 분모에 순환마디의 숫자 개수만큼 9를 써요.\n예: 0.444… = 4/9, 0.1212… = 12/99 = 4/33, 0.1222… = (12 − 1)/90 = 11/90"),
        ce(.middle, "유리수와 순환소수", ["유리수와 소수의 관계", "유리수와 순환소수의 관계"], "정수가 아닌 유리수는 유한소수나 순환소수로 나타낼 수 있어요. 거꾸로 유한소수와 순환소수는 모두 분수로 나타낼 수 있으므로 유리수예요. 그래서 순환하지 않는 무한소수는 유리수가 아니에요.\n예: 0.25 = 1/4, 0.333… = 1/3은 유리수이고, 3.141592…처럼 순환하지 않는 무한소수는 유리수가 아니에요."),
        ce(.middle, "식의 계산", ["단항식의 곱셈과 나눗셈", "단항식의 곱셈", "단항식의 나눗셈"], "단항식끼리 곱할 때는 계수끼리, 문자끼리 곱하고 같은 문자는 지수법칙을 이용해 간단히 해요. 나눗셈은 분수 꼴로 나타내거나 나누는 식의 역수를 곱해서 계산해요.\n예: 3a²b × 4ab³ = 12a³b⁴, 12x³y² ÷ 4xy = 3x²y"),
        ce(.middle, "식의 계산", ["다항식의 덧셈과 뺄셈", "이차식의 덧셈과 뺄셈", "동류항 정리"], "다항식의 덧셈과 뺄셈은 괄호를 풀고 동류항끼리 모아서 계산해요. 괄호 앞에 −가 있으면 괄호 안 모든 항의 부호를 바꾸어 풀어요. 차수가 가장 높은 항의 차수가 2인 다항식을 이차식이라고 해요.\n예: (2x² − 3x + 1) − (x² + x − 4) = x² − 4x + 5"),
        ce(.middle, "식의 계산", ["단항식과 다항식의 곱셈과 나눗셈", "분배법칙을 이용한 계산", "다항식 ÷ 단항식"], "단항식과 다항식의 곱셈은 분배법칙을 이용해 단항식을 다항식의 각 항에 곱해요. 다항식을 단항식으로 나눌 때는 다항식의 각 항을 단항식으로 나누어요.\n예: 2a(3a − b + 1) = 6a² − 2ab + 2a, (6x²y − 4xy) ÷ 2xy = 3x − 2"),
        ce(.middle, "일차부등식", ["부등식의 해", "부등식의 해와 수직선"], "부등식을 참이 되게 하는 미지수의 값을 그 부등식의 해라 하고, 해를 모두 구하는 것을 부등식을 푼다고 해요. 해는 수직선 위에 나타낼 수 있는데, 경계의 수를 포함하면 색칠한 점(●), 포함하지 않으면 빈 점(○)으로 표시해요.\n예: x > 2의 해는 2보다 큰 모든 수이고, 수직선에서 2에 ○를 하고 오른쪽으로 화살표를 그려요."),
        ce(.middle, "일차부등식", ["일차부등식의 풀이", "일차부등식", "linear inequality"], "부등식의 모든 항을 좌변으로 이항하여 정리했을 때 (일차식) > 0, (일차식) ≤ 0 등의 꼴이 되는 부등식을 일차부등식이라고 해요. 이항하여 ax > b 꼴로 만든 뒤 양변을 x의 계수로 나누는데, 계수가 음수이면 부등호의 방향을 바꿔요. 계수가 분수나 소수이면 양변에 적당한 수를 곱해 정수로 바꿔요.\n예: 3x − 7 ≤ 5x + 1 → −2x ≤ 8 → x ≥ −4"),
        ce(.middle, "일차부등식", ["일차부등식의 활용", "부등식 문장제"], "'이상', '이하', '초과', '미만', '적어도', '많아야' 같은 표현이 있으면 부등식을 세워요. 구한 해 중에서 문제의 조건(자연수, 개수 등)에 맞는 값만 답으로 골라요.\n예: 한 개에 700원인 빵을 사고 포장비 1000원을 낼 때 전체 금액이 8000원 이하가 되려면 700x + 1000 ≤ 8000, x ≤ 10이므로 빵은 최대 10개"),
        ce(.middle, "연립일차방정식", ["미지수가 2개인 일차방정식", "ax + by + c = 0"], "미지수가 x, y 두 개이고 차수가 모두 1인 방정식 ax + by + c = 0 (a ≠ 0, b ≠ 0)을 미지수가 2개인 일차방정식이라고 해요. 이 방정식을 참이 되게 하는 순서쌍 (x, y)가 해이고, 자연수 범위처럼 조건이 있으면 해를 하나씩 찾아볼 수 있어요.\n예: x, y가 자연수일 때 x + 2y = 7의 해는 (5, 1), (3, 2), (1, 3)"),
        ce(.middle, "연립일차방정식", ["해가 특수한 연립방정식", "해가 무수히 많은 연립방정식", "해가 없는 연립방정식"], "한 방정식의 양변에 어떤 수를 곱했을 때 다른 방정식과 완전히 같아지면 해가 무수히 많아요. x, y의 계수는 같아지는데 상수항만 다르면 두 식을 동시에 만족하는 해가 없어요.\n예: x + y = 2와 2x + 2y = 4는 해가 무수히 많고, x + y = 2와 x + y = 5는 해가 없어요."),
        ce(.middle, "연립일차방정식", ["연립방정식의 활용", "연립방정식 문장제"], "구하려는 두 양을 x, y로 놓고, 문제의 조건 두 개를 각각 방정식으로 세워 연립하여 풀어요. 구한 해가 문제의 뜻(자연수, 양수 등)에 맞는지 꼭 확인해요.\n예: 닭과 토끼가 모두 10마리이고 다리가 28개이면 x + y = 10, 2x + 4y = 28에서 닭 x = 6, 토끼 y = 4"),
        ce(.middle, "일차함수와 그래프", ["일차함수의 그래프의 평행이동", "y = ax + b의 그래프"], "일차함수 y = ax + b의 그래프는 y = ax의 그래프를 y축의 방향으로 b만큼 평행이동한 직선이에요. 평행이동하면 모양과 기울기는 그대로이고 위치만 바뀌어요.\n예: y = 2x − 3의 그래프는 y = 2x의 그래프를 y축의 방향으로 −3만큼 평행이동한 거예요."),
        ce(.middle, "일차함수와 그래프", ["x절편과 y절편", "x절편", "y절편", "절편"], "그래프가 x축과 만나는 점의 x좌표를 x절편, y축과 만나는 점의 y좌표를 y절편이라고 해요. x절편은 y = 0을, y절편은 x = 0을 대입해서 구해요. 두 절편을 알면 두 점을 이어 그래프를 쉽게 그릴 수 있어요.\n예: y = −2x + 6의 x절편은 3, y절편은 6이에요."),
        ce(.middle, "일차함수와 그래프", ["일차함수의 그래프의 성질", "기울기의 부호", "두 직선의 평행과 일치"], "y = ax + b에서 a > 0이면 x가 증가할 때 y도 증가하고(오른쪽 위로 향하는 직선), a < 0이면 y가 감소해요(오른쪽 아래로 향하는 직선). 기울기가 같고 y절편이 다르면 두 직선은 평행하고, 기울기와 y절편이 모두 같으면 일치해요.\n예: y = 3x + 1과 y = 3x − 2는 평행해요."),
        ce(.middle, "일차함수와 그래프", ["일차함수의 활용", "일차함수 문장제"], "변하는 두 양 사이의 관계를 y = ax + b로 나타낸 뒤, 주어진 x의 값이나 y의 값을 대입해 필요한 값을 구해요. 처음의 양이 b이고 일정하게 a씩 변하는 상황이 대표적이에요.\n예: 길이가 20cm인 양초가 1분에 0.5cm씩 탄다면 x분 후 길이는 y = 20 − 0.5x이고, 다 타는 데 40분이 걸려요."),
        ce(.middle, "일차함수와 일차방정식의 관계", ["일차방정식의 그래프", "ax + by + c = 0의 그래프"], "미지수가 2개인 일차방정식 ax + by + c = 0의 해를 좌표평면 위에 나타내면 직선이 되는데, 이것을 일차방정식의 그래프라고 해요. b ≠ 0이면 y = −(a/b)x − c/b로 바꿀 수 있으므로 일차함수의 그래프와 같아요.\n예: 2x − y + 3 = 0은 y = 2x + 3과 같으므로 기울기 2, y절편 3인 직선이에요."),
        ce(.middle, "일차함수와 일차방정식의 관계", ["좌표축에 평행한 직선", "x = p의 그래프", "y = q의 그래프"], "방정식 x = p (p는 상수)의 그래프는 점 (p, 0)을 지나고 y축에 평행한 직선이고, y = q의 그래프는 점 (0, q)를 지나고 x축에 평행한 직선이에요. x = p는 x의 값 하나에 y의 값이 무수히 많으므로 함수가 아니에요.\n예: x = 3의 그래프는 (3, 0)을 지나는 세로선, y = −2의 그래프는 (0, −2)를 지나는 가로선이에요."),
        ce(.middle, "삼각형의 성질", ["삼각형의 외심", "외심", "외접원", "circumcenter"], "삼각형의 세 변의 수직이등분선은 한 점에서 만나는데, 이 점을 외심이라고 해요. 외심에서 세 꼭짓점까지의 거리는 같으므로 외심은 외접원의 중심이에요. 외심은 예각삼각형에서는 삼각형의 내부, 직각삼각형에서는 빗변의 중점, 둔각삼각형에서는 삼각형의 외부에 있어요.\n예: 빗변의 길이가 10인 직각삼각형의 외접원의 반지름은 5예요."),
        ce(.middle, "삼각형의 성질", ["삼각형의 내심", "내심", "내접원", "incenter"], "삼각형의 세 내각의 이등분선은 한 점에서 만나는데, 이 점을 내심이라고 해요. 내심에서 세 변까지의 거리는 같으므로 내심은 내접원의 중심이에요. 내접원의 반지름을 r, 세 변의 길이를 a, b, c라 하면 삼각형의 넓이는 (1/2)r(a + b + c)예요.\n예: 세 변이 3, 4, 5인 직각삼각형의 넓이는 6이므로 6 = (1/2) × r × 12에서 내접원의 반지름은 1이에요."),
        ce(.middle, "삼각형의 성질", ["직각삼각형의 합동 조건", "RHA 합동", "RHS 합동"], "두 직각삼각형은 ① 빗변의 길이와 한 예각의 크기가 각각 같을 때(RHA 합동), ② 빗변의 길이와 다른 한 변의 길이가 각각 같을 때(RHS 합동) 서로 합동이에요. R은 직각(Right angle), H는 빗변(Hypotenuse), A는 각(Angle), S는 변(Side)을 뜻해요.\n예: 빗변이 5로 같고 한 변이 3으로 같은 두 직각삼각형은 RHS 합동이에요."),
        ce(.middle, "삼각형의 성질", ["각의 이등분선의 성질", "각의 이등분선"], "각의 이등분선 위의 한 점에서 그 각의 두 변까지의 거리는 같아요. 거꾸로 각의 두 변에서 같은 거리에 있는 점은 그 각의 이등분선 위에 있어요. 이 성질은 직각삼각형의 합동(RHA, RHS)으로 설명할 수 있어요.\n예: ∠AOB의 이등분선 위의 점 P에서 두 변 OA, OB에 내린 수선의 길이는 같아요."),
        ce(.middle, "사각형의 성질", ["평행사변형이 되는 조건", "평행사변형의 조건"], "사각형이 다음 중 하나를 만족하면 평행사변형이에요. ① 두 쌍의 대변이 각각 평행하다. ② 두 쌍의 대변의 길이가 각각 같다. ③ 두 쌍의 대각의 크기가 각각 같다. ④ 두 대각선이 서로를 이등분한다. ⑤ 한 쌍의 대변이 평행하고 그 길이가 같다.\n예: AD // BC이고 AD = BC인 사각형 ABCD는 평행사변형이에요."),
        ce(.middle, "사각형의 성질", ["여러 가지 사각형", "직사각형의 성질", "마름모의 성질", "정사각형의 성질", "등변사다리꼴"], "직사각형은 네 내각의 크기가 모두 같은 사각형으로 두 대각선의 길이가 같고 서로를 이등분해요. 마름모는 네 변의 길이가 모두 같은 사각형으로 두 대각선이 서로를 수직이등분해요. 정사각형은 직사각형과 마름모의 성질을 모두 가지고, 등변사다리꼴은 아랫변의 양 끝 각의 크기가 같은 사다리꼴로 두 대각선의 길이가 같아요.\n예: 두 대각선의 길이가 같고 서로를 수직이등분하는 사각형은 정사각형이에요."),
        ce(.middle, "사각형의 성질", ["사각형 사이의 관계", "사다리꼴"], "사다리꼴은 한 쌍의 대변이 평행한 사각형이고, 다른 한 쌍의 대변도 평행하면 평행사변형이 돼요. 평행사변형에 한 내각이 직각이라는 조건을 더하면 직사각형, 이웃하는 두 변의 길이가 같다는 조건을 더하면 마름모가 되고, 직사각형이면서 마름모인 사각형이 정사각형이에요.\n예: 정사각형은 직사각형이고 마름모이지만, 평행사변형이 항상 직사각형인 것은 아니에요."),
        ce(.middle, "사각형의 성질", ["평행선과 넓이", "넓이가 같은 삼각형"], "두 직선 l, m이 평행할 때, 밑변이 같고 꼭짓점이 직선 l 위에 있는 삼각형들은 높이가 같으므로 넓이가 모두 같아요. 또 높이가 같은 두 삼각형의 넓이의 비는 밑변의 길이의 비와 같아요.\n예: AD // BC인 사다리꼴 ABCD에서 △ABC와 △DBC의 넓이는 같아요."),
        ce(.middle, "도형의 닮음", ["직각삼각형의 닮음", "직각삼각형에서 닮음의 활용"], "∠A = 90°인 직각삼각형 ABC의 꼭짓점 A에서 빗변 BC에 내린 수선의 발을 H라고 하면 △ABC, △HBA, △HAC는 모두 닮음이에요. 그래서 AB² = BH × BC, AC² = CH × CB, AH² = BH × CH가 성립해요.\n예: BH = 4, CH = 9이면 AH² = 4 × 9 = 36이므로 AH = 6이에요."),
        ce(.middle, "도형의 닮음", ["닮음의 활용", "축도와 축척"], "닮음을 이용하면 직접 재기 어려운 높이나 거리를 구할 수 있어요. 실제 도형을 일정한 비율로 줄여 그린 그림을 축도, 줄인 비율을 축척이라고 해요.\n예: 길이 1m인 막대의 그림자가 1.5m일 때 그림자가 6m인 나무의 높이는 1 : 1.5 = x : 6에서 4m예요."),
        ce(.middle, "평행선과 선분의 길이의 비", ["삼각형에서 평행선과 선분의 길이의 비", "평행선과 선분의 비"], "△ABC에서 변 BC에 평행한 직선이 두 변 AB, AC 또는 그 연장선과 만나는 점을 각각 D, E라고 하면 AD : AB = AE : AC = DE : BC이고, AD : DB = AE : EC예요. 거꾸로 AD : DB = AE : EC이면 DE와 BC는 평행해요.\n예: AD = 4, DB = 2, AE = 6이면 4 : 2 = 6 : EC이므로 EC = 3이에요."),
        ce(.middle, "평행선과 선분의 길이의 비", ["삼각형의 두 변의 중점을 연결한 선분의 성질", "중점연결정리"], "삼각형의 두 변의 중점을 연결한 선분은 나머지 한 변과 평행하고, 그 길이는 나머지 한 변의 길이의 1/2이에요. 거꾸로 한 변의 중점을 지나고 다른 한 변에 평행한 직선은 나머지 한 변의 중점을 지나요.\n예: △ABC에서 AB, AC의 중점을 M, N이라 할 때 BC = 10이면 MN = 5예요."),
        ce(.middle, "평행선과 선분의 길이의 비", ["삼각형의 각의 이등분선과 선분의 비", "내각의 이등분선과 선분의 비"], "△ABC에서 ∠A의 이등분선이 변 BC와 만나는 점을 D라고 하면 AB : AC = BD : DC예요. 즉 내각의 이등분선은 마주 보는 변을 이웃한 두 변의 길이의 비로 나누어요.\n예: AB = 6, AC = 4, BC = 5이면 BD : DC = 3 : 2이므로 BD = 3, DC = 2예요."),
        ce(.middle, "평행선과 선분의 길이의 비", ["평행선 사이의 선분의 길이의 비", "평행선에 의해 잘린 선분"], "세 개 이상의 평행선이 다른 두 직선과 만날 때, 평행선 사이에 생기는 선분의 길이의 비는 같아요. 즉 l // m // n이고 두 직선이 이 평행선과 만나는 점을 각각 A, B, C와 D, E, F라 하면 AB : BC = DE : EF예요.\n예: AB = 3, BC = 6, DE = 2이면 EF = 4예요."),
        ce(.middle, "삼각형의 무게중심", ["삼각형의 중선", "중선", "중선과 넓이"], "삼각형의 한 꼭짓점과 그 대변의 중점을 이은 선분을 중선이라고 해요. 삼각형의 중선은 그 삼각형의 넓이를 이등분해요.\n예: △ABC에서 BC의 중점을 M이라 하면 △ABM과 △AMC의 넓이는 같아요."),
        ce(.middle, "삼각형의 무게중심", ["무게중심과 넓이", "삼각형의 무게중심과 넓이"], "삼각형의 세 중선은 삼각형을 넓이가 같은 6개의 삼각형으로 나누어요. 그래서 무게중심 G와 세 꼭짓점을 이어 만든 세 삼각형 △GAB, △GBC, △GCA의 넓이는 각각 △ABC의 넓이의 1/3이에요.\n예: △ABC의 넓이가 36이면 △GBC의 넓이는 12예요."),
        ce(.middle, "피타고라스 정리", ["피타고라스 정리의 증명", "유클리드의 증명"], "피타고라스 정리는 여러 가지 방법으로 증명할 수 있어요. 직각삼각형의 세 변을 각각 한 변으로 하는 정사각형을 그리고, 빗변 위 정사각형의 넓이가 나머지 두 정사각형의 넓이의 합과 같음을 넓이를 옮겨 보이는 방법(유클리드)이 대표적이에요. 합동인 직각삼각형 4개를 큰 정사각형 안에 배치해 넓이를 두 가지로 나타내는 방법도 있어요.\n예: 한 변이 a + b인 정사각형 안에 직각삼각형 4개를 놓으면 (a + b)² = 4 × (1/2)ab + c²이므로 a² + b² = c²"),
        ce(.middle, "피타고라스 정리", ["직각삼각형이 되는 조건", "피타고라스 정리의 역", "피타고라스의 정리의 역"], "세 변의 길이가 a, b, c인 삼각형에서 a² + b² = c²이 성립하면 이 삼각형은 빗변의 길이가 c인 직각삼각형이에요. 이것을 피타고라스 정리의 역이라고 해요. 판별할 때는 가장 긴 변을 c로 놓고 확인해요.\n예: 세 변이 5, 12, 13이면 5² + 12² = 169 = 13²이므로 직각삼각형이고, 4, 5, 6은 16 + 25 ≠ 36이므로 직각삼각형이 아니에요."),
        ce(.middle, "피타고라스 정리", ["삼각형의 변의 길이와 각의 크기 사이의 관계", "예각삼각형과 둔각삼각형의 판별"], "가장 긴 변의 길이가 c이고 나머지 두 변의 길이가 a, b인 삼각형에서 c² < a² + b²이면 예각삼각형, c² = a² + b²이면 직각삼각형, c² > a² + b²이면 둔각삼각형이에요.\n예: 세 변이 4, 5, 6이면 36 < 16 + 25이므로 예각삼각형, 3, 4, 6이면 36 > 9 + 16이므로 둔각삼각형이에요."),
        ce(.middle, "피타고라스 정리", ["피타고라스 정리의 활용", "대각선의 길이", "정삼각형의 높이", "직육면체의 대각선"], "피타고라스 정리를 이용하면 여러 도형의 길이를 구할 수 있어요. 가로 a, 세로 b인 직사각형의 대각선은 √(a² + b²), 한 변이 a인 정삼각형의 높이는 (√3/2)a, 가로·세로·높이가 a, b, c인 직육면체의 대각선은 √(a² + b² + c²)이에요. 좌표평면에서 두 점 사이의 거리도 피타고라스 정리로 구해요.\n예: 가로 3, 세로 4인 직사각형의 대각선은 5, 두 점 (1, 2), (4, 6) 사이의 거리는 5예요."),
        ce(.middle, "피타고라스 정리", ["피타고라스 수", "피타고라스 세 쌍"], "a² + b² = c²을 만족하는 세 자연수 a, b, c를 피타고라스 수라고 해요. 피타고라스 수인 세 수에 같은 자연수를 곱해도 다시 피타고라스 수가 돼요.\n예: (3, 4, 5), (5, 12, 13), (8, 15, 17), (7, 24, 25), (6, 8, 10)은 피타고라스 수예요."),
        ce(.middle, "경우의 수와 확률", ["한 줄로 세우는 경우의 수", "줄 세우기"], "n명을 한 줄로 세우는 경우의 수는 n × (n − 1) × … × 2 × 1이에요. n명 중 r명만 뽑아 한 줄로 세우는 경우의 수는 n부터 1씩 작아지는 수를 r개 곱한 값이에요.\n예: 4명을 한 줄로 세우는 경우의 수는 4 × 3 × 2 × 1 = 24, 5명 중 2명을 뽑아 한 줄로 세우는 경우의 수는 5 × 4 = 20"),
        ce(.middle, "경우의 수와 확률", ["대표를 뽑는 경우의 수", "자격이 같은 대표 뽑기"], "n명 중에서 회장 1명, 부회장 1명처럼 자격이 다른 대표 2명을 뽑는 경우의 수는 n × (n − 1)이에요. 자격이 같은 대표 2명을 뽑을 때는 순서를 생각하지 않으므로 n × (n − 1) ÷ 2예요.\n예: 5명 중 회장과 부회장을 뽑는 경우는 20가지, 대표 2명을 뽑는 경우는 10가지예요."),
        ce(.middle, "경우의 수와 확률", ["확률의 계산", "확률의 덧셈", "확률의 곱셈"], "두 사건 A, B가 동시에 일어나지 않을 때 A 또는 B가 일어날 확률은 두 확률의 합이에요. 두 사건 A, B가 서로 영향을 끼치지 않을 때 A와 B가 동시에 일어날 확률은 두 확률의 곱이에요. 꺼낸 것을 다시 넣지 않으면 두 번째 확률을 계산할 때 전체 개수가 줄어드는 것에 주의해요.\n예: 빨간 공 3개, 파란 공 2개 중 꺼낸 공을 다시 넣지 않고 두 번 모두 빨간 공을 꺼낼 확률은 3/5 × 2/4 = 3/10"),

        // 중3
        ce(.middle, "제곱근과 실수", ["제곱근의 성질", "√(a²) = |a|"], "a > 0일 때 (√a)² = a, (−√a)² = a, √(a²) = a, √((−a)²) = a예요. 일반적으로 √(a²)은 a ≥ 0이면 a, a < 0이면 −a이므로 a의 절댓값과 같아요.\n예: √(5²) = 5, √((−5)²) = 5, x < 0일 때 √(x²) = −x"),
        ce(.middle, "제곱근과 실수", ["제곱근의 대소 관계", "제곱근의 크기 비교"], "a > 0, b > 0일 때 a < b이면 √a < √b이고, √a < √b이면 a < b예요. 근호가 없는 수와 비교할 때는 그 수를 근호를 사용해 나타내거나 두 수를 각각 제곱하여 비교해요. 음수끼리는 절댓값이 큰 쪽이 작아요.\n예: 3 = √9이므로 √8 < 3, −√5 > −√7"),
        ce(.middle, "제곱근과 실수", ["실수와 수직선", "실수의 대소 관계"], "모든 실수는 수직선 위의 한 점에 대응하고, 수직선은 실수에 대응하는 점들로 완전히 메울 수 있어요. 서로 다른 두 실수 사이에는 무수히 많은 실수가 있어요. 두 실수의 대소는 뺄셈을 하여 그 결과의 부호로 비교할 수 있어요.\n예: 한 변이 1인 정사각형의 대각선 길이 √2를 컴퍼스로 옮기면 수직선 위에서 √2에 대응하는 점을 찾을 수 있어요."),
        ce(.middle, "근호를 포함한 식의 계산", ["제곱근의 곱셈과 나눗셈", "근호 안의 수 꺼내기"], "a > 0, b > 0일 때 √a × √b = √(ab), √a ÷ √b = √(a/b)예요. 근호 안의 제곱인 인수는 근호 밖으로 꺼낼 수 있어서 √(a²b) = a√b이고, 거꾸로 a√b = √(a²b)로 근호 안에 넣을 수도 있어요.\n예: √3 × √12 = √36 = 6, √50 = 5√2, 2√3 = √12"),
        ce(.middle, "근호를 포함한 식의 계산", ["분모의 유리화", "유리화"], "분모가 근호를 포함한 무리수일 때 분모와 분자에 0이 아닌 같은 수를 곱하여 분모를 유리수로 고치는 것을 분모의 유리화라고 해요. a > 0일 때 b/√a = b√a/a예요.\n예: 3/√3 = 3√3/3 = √3, 1/(2√5) = √5/10"),
        ce(.middle, "근호를 포함한 식의 계산", ["제곱근의 덧셈과 뺄셈", "근호를 포함한 식의 덧셈과 뺄셈"], "근호 안의 수가 같은 것끼리는 동류항처럼 계수끼리 더하거나 빼요. 근호 안의 수가 다르면 먼저 √(a²b) = a√b를 이용해 근호 안을 가장 작은 자연수로 바꾼 뒤 계산해요. √a + √b와 √(a + b)는 같지 않아요.\n예: 2√3 + 5√3 = 7√3, √8 + √18 = 2√2 + 3√2 = 5√2"),
        ce(.middle, "근호를 포함한 식의 계산", ["근호를 포함한 식의 혼합 계산", "제곱근의 혼합 계산"], "괄호가 있으면 분배법칙으로 괄호를 풀고, 곱셈과 나눗셈을 덧셈과 뺄셈보다 먼저 계산해요. 분모에 근호가 있으면 유리화한 뒤 근호 안의 수가 같은 것끼리 정리해요.\n예: √2(√6 + √2) = √12 + 2 = 2√3 + 2"),
        ce(.middle, "다항식의 곱셈과 인수분해", ["곱셈 공식의 활용", "곱셈 공식을 이용한 수의 계산"], "곱셈 공식을 이용하면 복잡한 수의 계산이나 식의 값을 간단히 구할 수 있어요. 102²처럼 어떤 수에 가까운 수의 제곱은 (a + b)²을, 51 × 49처럼 합과 차의 곱은 (a + b)(a − b)를 이용해요. 또 a + b와 ab의 값을 알면 a² + b² = (a + b)² − 2ab로 구할 수 있어요.\n예: 102² = (100 + 2)² = 10404, a + b = 5, ab = 3이면 a² + b² = 25 − 6 = 19"),
        ce(.middle, "다항식의 곱셈과 인수분해", ["인수분해 공식", "acx² + (ad + bc)x + bd의 인수분해"], "자주 쓰는 인수분해 공식은 ① a² ± 2ab + b² = (a ± b)² ② a² − b² = (a + b)(a − b) ③ x² + (a + b)x + ab = (x + a)(x + b) ④ acx² + (ad + bc)x + bd = (ax + b)(cx + d)예요. ③은 곱이 상수항, 합이 x의 계수인 두 수를 찾고, ④는 십자 모양으로 계수를 맞추어 찾아요.\n예: x² + x − 12 = (x + 4)(x − 3), 6x² + x − 2 = (2x − 1)(3x + 2)"),
        ce(.middle, "다항식의 곱셈과 인수분해", ["인수분해의 활용", "인수분해를 이용한 수의 계산"], "인수분해 공식을 이용하면 수의 계산을 간단히 할 수 있어요. 공통부분이 있는 식은 그 부분을 한 문자로 바꾸어 인수분해한 뒤 원래대로 돌려놓아요.\n예: 57² − 43² = (57 + 43)(57 − 43) = 100 × 14 = 1400, (x + 1)² − 3(x + 1) + 2에서 x + 1 = A로 놓으면 (A − 1)(A − 2) = x(x − 1)"),
        ce(.middle, "이차방정식", ["인수분해를 이용한 이차방정식의 풀이", "AB = 0의 성질"], "두 수 또는 두 식 A, B에 대하여 AB = 0이면 A = 0 또는 B = 0이에요. 그래서 이차방정식을 (x − a)(x − b) = 0 꼴로 인수분해하면 해는 x = a 또는 x = b예요. 두 해가 서로 같으면 그 해를 중근이라고 해요.\n예: x² − 7x + 10 = 0 → (x − 2)(x − 5) = 0 → x = 2 또는 x = 5, x² − 6x + 9 = 0 → (x − 3)² = 0 → x = 3 (중근)"),
        ce(.middle, "이차방정식", ["제곱근을 이용한 이차방정식의 풀이", "완전제곱식을 이용한 풀이"], "x² = k (k ≥ 0)이면 x = ±√k이고, (x − p)² = q (q ≥ 0)이면 x = p ± √q예요. 인수분해가 어려운 이차방정식은 (x − p)² = q 꼴로 완전제곱식을 만들어 풀 수 있어요.\n예: (x − 1)² = 5 → x = 1 ± √5, x² + 4x − 1 = 0 → (x + 2)² = 5 → x = −2 ± √5"),
        ce(.middle, "이차방정식", ["이차방정식의 활용", "이차방정식 문장제"], "문제의 뜻에 맞게 미지수를 정하고 이차방정식을 세워 푼 뒤, 구한 해 중에서 길이나 개수처럼 문제의 조건에 맞는 것만 답으로 해요. 해가 두 개일 수 있으므로 음수나 0이 되는 해를 버려야 하는지 꼭 확인해요.\n예: 연속하는 두 자연수의 곱이 56이면 x(x + 1) = 56, (x + 8)(x − 7) = 0이므로 x = 7이고 두 수는 7과 8"),
        ce(.middle, "이차함수와 그래프", ["이차함수 y = ax²의 그래프", "y = ax²의 그래프", "포물선"], "이차함수 y = ax² (a ≠ 0)의 그래프는 원점을 꼭짓점으로 하고 y축을 축으로 하는 포물선이에요. a > 0이면 아래로 볼록, a < 0이면 위로 볼록하고, a의 절댓값이 클수록 그래프의 폭이 좁아져요. y = ax²과 y = −ax²의 그래프는 x축에 대하여 서로 대칭이에요.\n예: y = 2x²의 그래프는 y = x²의 그래프보다 폭이 좁고, 점 (1, 2)를 지나요."),
        ce(.middle, "이차함수와 그래프", ["y = a(x − p)² + q의 그래프", "이차함수의 평행이동", "꼭짓점과 축"], "y = a(x − p)² + q의 그래프는 y = ax²의 그래프를 x축의 방향으로 p만큼, y축의 방향으로 q만큼 평행이동한 포물선이에요. 꼭짓점의 좌표는 (p, q), 축의 방정식은 x = p예요.\n예: y = −(x + 1)² + 4의 꼭짓점은 (−1, 4), 축은 x = −1이고 위로 볼록해요."),
        ce(.middle, "이차함수와 그래프", ["y = ax² + bx + c의 그래프", "이차함수의 그래프 그리기"], "y = ax² + bx + c는 완전제곱식을 이용해 y = a(x − p)² + q 꼴로 바꾸면 꼭짓점과 축을 알 수 있어요. 그래프는 y축과 점 (0, c)에서 만나고, x축과의 교점의 x좌표는 ax² + bx + c = 0의 해예요.\n예: y = x² − 2x − 3 = (x − 1)² − 4는 꼭짓점 (1, −4), y절편 −3이고 x축과 x = −1, 3에서 만나요."),
        ce(.middle, "삼각비", ["0°와 90°의 삼각비", "삼각비의 값의 범위"], "sin 0° = 0, cos 0° = 1, tan 0° = 0, sin 90° = 1, cos 90° = 0이고 tan 90°의 값은 정할 수 없어요. 0° ≤ x ≤ 90°에서 x가 커지면 sin x는 0에서 1까지 커지고, cos x는 1에서 0까지 작아지며, tan x는 0부터 한없이 커져요.\n예: sin 20° < sin 70°이고 cos 20° > cos 70°예요."),
        ce(.middle, "삼각비", ["삼각비의 표", "삼각비표"], "0°부터 90°까지 1° 간격으로 삼각비의 값을 반올림하여 소수 넷째 자리까지 나타낸 표를 삼각비의 표라고 해요. 표에서 각도의 가로줄과 sin, cos, tan의 세로줄이 만나는 곳의 값을 읽어요.\n예: 삼각비의 표에서 sin 25° ≈ 0.4226, cos 25° ≈ 0.9063이에요."),
        ce(.middle, "삼각비", ["삼각비를 이용한 길이 구하기", "높이 구하기"], "직각삼각형에서 한 변의 길이와 한 예각의 크기를 알면 삼각비로 나머지 변의 길이를 구할 수 있어요. 빗변이 c이고 한 예각이 A이면 A의 대변은 c sin A, 이웃변은 c cos A예요. 이를 이용해 건물이나 나무의 높이처럼 직접 재기 어려운 길이를 구해요.\n예: 나무에서 10m 떨어진 곳에서 나무 꼭대기를 올려다본 각이 45°이면 (눈높이를 무시할 때) 나무의 높이는 10 × tan 45° = 10m예요."),
        ce(.middle, "삼각비", ["삼각비를 이용한 넓이 구하기", "삼각형의 넓이 공식"], "두 변의 길이가 a, b이고 그 끼인각 x가 예각이면 삼각형의 넓이는 (1/2)ab sin x, 둔각이면 (1/2)ab sin(180° − x)예요. 이웃하는 두 변의 길이가 a, b이고 끼인각이 x (예각)인 평행사변형의 넓이는 ab sin x예요.\n예: 두 변이 4, 6이고 끼인각이 150°인 삼각형의 넓이는 (1/2) × 4 × 6 × sin 30° = 6"),
        ce(.middle, "원의 성질", ["원의 중심과 현의 수직이등분선", "현의 수직이등분선", "원의 중심과 현의 길이"], "원의 중심에서 현에 내린 수선은 그 현을 이등분하고, 현의 수직이등분선은 원의 중심을 지나요. 한 원에서 중심으로부터 같은 거리에 있는 두 현의 길이는 같고, 길이가 같은 두 현은 중심으로부터 같은 거리에 있어요.\n예: 반지름이 5인 원에서 중심과의 거리가 3인 현의 길이는 2 × √(5² − 3²) = 8이에요."),
        ce(.middle, "원의 성질", ["원주각의 크기와 호의 길이", "원주각과 호"], "한 원에서 길이가 같은 호에 대한 원주각의 크기는 같고, 크기가 같은 원주각에 대한 호의 길이도 같아요. 원주각의 크기는 호의 길이에 정비례해요.\n예: 원주각이 20°인 호의 길이가 3cm이면, 원주각이 60°인 호의 길이는 9cm예요."),
        ce(.middle, "원의 성질", ["원에 내접하는 사각형", "내접사각형의 성질"], "원에 내접하는 사각형에서 한 쌍의 대각의 크기의 합은 180°이고, 한 외각의 크기는 그 내각의 대각의 크기와 같아요. 거꾸로 한 쌍의 대각의 크기의 합이 180°인 사각형은 원에 내접해요.\n예: 원에 내접하는 사각형 ABCD에서 ∠A = 75°이면 ∠C = 105°예요."),
        ce(.middle, "원의 성질", ["접선과 현이 이루는 각", "접현각"], "원의 접선과 그 접점을 지나는 현이 이루는 각의 크기는 그 각의 내부에 있는 호에 대한 원주각의 크기와 같아요.\n예: 접선과 현 AB가 이루는 각이 70°이면 그 각 안쪽의 호 AB에 대한 원주각도 70°예요."),
        ce(.middle, "원의 성질", ["원에 외접하는 사각형", "외접사각형의 성질"], "원 밖의 한 점에서 그은 두 접선의 길이가 같다는 성질을 이용하면, 원에 외접하는 사각형에서 두 쌍의 대변의 길이의 합이 서로 같다는 것을 알 수 있어요.\n예: 원에 외접하는 사각형 ABCD에서 AB = 7, CD = 9, AD = 6이면 BC = 7 + 9 − 6 = 10이에요."),
        ce(.middle, "대푯값과 산포도", ["상자그림", "box plot", "사분위수"], "상자그림은 자료의 최솟값, 제1사분위수, 중앙값, 제3사분위수, 최댓값의 다섯 가지 값으로 자료의 분포를 나타낸 그림이에요. 자료를 크기순으로 늘어놓았을 때 하위 25%에 해당하는 값이 제1사분위수, 상위 25%에 해당하는 값이 제3사분위수이고, 상자의 길이가 길수록 가운데 절반의 자료가 넓게 흩어져 있어요.\n예: 두 반의 수학 점수를 상자그림으로 나란히 그리면 중앙값과 흩어진 정도를 한눈에 비교할 수 있어요."),
        ce(.middle, "대푯값과 산포도", ["적절한 대푯값 고르기", "대푯값의 선택"], "자료에 극단적으로 크거나 작은 값이 있으면 평균은 그 값의 영향을 크게 받으므로 중앙값이 자료의 중심을 더 잘 나타내요. 옷이나 신발의 치수처럼 가장 많이 팔린 것을 알고 싶을 때는 최빈값이 알맞아요.\n예: 월급이 200, 210, 220, 230, 2000만 원인 다섯 사람의 평균은 572만 원이지만 중앙값은 220만 원이에요."),
        ce(.middle, "상관관계", ["산점도", "scatter plot"], "두 변량 x, y의 순서쌍 (x, y)를 좌표평면 위에 점으로 나타낸 그래프를 산점도라고 해요. 산점도를 그리면 두 변량 사이에 어떤 관계가 있는지 한눈에 알 수 있어요.\n예: 학생 10명의 (키, 몸무게)를 좌표평면에 점으로 찍으면 산점도가 돼요."),
        ce(.middle, "상관관계", ["상관관계", "양의 상관관계", "음의 상관관계", "correlation"], "두 변량 중 한쪽이 커질 때 다른 쪽도 대체로 커지는 관계를 양의 상관관계, 대체로 작아지는 관계를 음의 상관관계라고 해요. 한쪽이 커질 때 다른 쪽이 커지는지 작아지는지 분명하지 않으면 상관관계가 없다고 해요.\n예: 키와 몸무게는 양의 상관관계, 산의 높이와 기온은 음의 상관관계, 키와 수학 점수는 상관관계가 거의 없어요."),
        ce(.middle, "상관관계", ["상관관계의 강약", "강한 상관관계", "약한 상관관계"], "산점도에서 점들이 한 직선 가까이에 모여 있을수록 상관관계가 강하고, 직선에서 멀리 흩어져 있을수록 상관관계가 약하다고 해요.\n예: 공부 시간과 성적을 나타낸 점들이 오른쪽 위로 향하는 직선 가까이에 몰려 있으면 강한 양의 상관관계예요."),
        ce(.middle, "상관관계", ["상관관계와 인과관계", "인과관계"], "두 변량 사이에 상관관계가 있다고 해서 한쪽이 다른 쪽의 원인이라고 단정할 수는 없어요. 두 변량 모두에 영향을 주는 다른 요인이 있을 수 있기 때문이에요.\n예: 아이스크림 판매량과 물놀이 사고 수는 양의 상관관계가 있지만, 둘 다 기온이 높을 때 늘어나는 것이지 아이스크림이 사고의 원인은 아니에요.")
    ]
}
